class Sequence extends DataClass implements Insertable<Sequence> {
  final int id;
  final String name;
  final String? description;
  final String? rootNodeId;
  final int estimatedDurationMins;
  final DateTime createdAt;
  final DateTime updatedAt;
  final bool isTemplate;

  /// Library tags as a JSON-encoded `List<String>` (e.g. `["narrowband",
  /// "winter"]`). Defaults to an empty-list literal so existing rows and new
  /// inserts that omit it read back as "no tags" rather than null. Stored as
  /// JSON in a single column rather than a join table because tags are a
  /// lightweight, display-only library filter — there is no relational query
  /// against individual tags.
  final String tagsJson;

  /// Library favorite flag. Drives the "starred" filter/sort in the sequence
  /// library. Defaults to false.
  final bool isFavorite;
  const Sequence({
    required this.id,
    required this.name,
    this.description,
    this.rootNodeId,
    required this.estimatedDurationMins,
    required this.createdAt,
    required this.updatedAt,
    required this.isTemplate,
    required this.tagsJson,
    required this.isFavorite,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    if (!nullToAbsent || rootNodeId != null) {
      map['root_node_id'] = Variable<String>(rootNodeId);
    }
    map['estimated_duration_mins'] = Variable<int>(estimatedDurationMins);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['is_template'] = Variable<bool>(isTemplate);
    map['tags_json'] = Variable<String>(tagsJson);
    map['is_favorite'] = Variable<bool>(isFavorite);
    return map;
  }

  SequencesCompanion toCompanion(bool nullToAbsent) {
    return SequencesCompanion(
      id: Value(id),
      name: Value(name),
      description: description == null && nullToAbsent
          ? const Value.absent()
          : Value(description),
      rootNodeId: rootNodeId == null && nullToAbsent
          ? const Value.absent()
          : Value(rootNodeId),
      estimatedDurationMins: Value(estimatedDurationMins),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      isTemplate: Value(isTemplate),
      tagsJson: Value(tagsJson),
      isFavorite: Value(isFavorite),
    );
  }

  factory Sequence.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Sequence(
      id: serializer.fromJson<int>(json['id']),
      name: serializer.fromJson<String>(json['name']),
      description: serializer.fromJson<String?>(json['description']),
      rootNodeId: serializer.fromJson<String?>(json['rootNodeId']),
      estimatedDurationMins: serializer.fromJson<int>(
        json['estimatedDurationMins'],
      ),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      isTemplate: serializer.fromJson<bool>(json['isTemplate']),
      tagsJson: serializer.fromJson<String>(json['tagsJson']),
      isFavorite: serializer.fromJson<bool>(json['isFavorite']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'name': serializer.toJson<String>(name),
      'description': serializer.toJson<String?>(description),
      'rootNodeId': serializer.toJson<String?>(rootNodeId),
      'estimatedDurationMins': serializer.toJson<int>(estimatedDurationMins),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
      'isTemplate': serializer.toJson<bool>(isTemplate),
      'tagsJson': serializer.toJson<String>(tagsJson),
      'isFavorite': serializer.toJson<bool>(isFavorite),
    };
  }

  Sequence copyWith({
    int? id,
    String? name,
    Value<String?> description = const Value.absent(),
    Value<String?> rootNodeId = const Value.absent(),
    int? estimatedDurationMins,
    DateTime? createdAt,
    DateTime? updatedAt,
    bool? isTemplate,
    String? tagsJson,
    bool? isFavorite,
  }) => Sequence(
    id: id ?? this.id,
    name: name ?? this.name,
    description: description.present ? description.value : this.description,
    rootNodeId: rootNodeId.present ? rootNodeId.value : this.rootNodeId,
    estimatedDurationMins: estimatedDurationMins ?? this.estimatedDurationMins,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
    isTemplate: isTemplate ?? this.isTemplate,
    tagsJson: tagsJson ?? this.tagsJson,
    isFavorite: isFavorite ?? this.isFavorite,
  );
  Sequence copyWithCompanion(SequencesCompanion data) {
    return Sequence(
      id: data.id.present ? data.id.value : this.id,
      name: data.name.present ? data.name.value : this.name,
      description: data.description.present
          ? data.description.value
          : this.description,
      rootNodeId: data.rootNodeId.present
          ? data.rootNodeId.value
          : this.rootNodeId,
      estimatedDurationMins: data.estimatedDurationMins.present
          ? data.estimatedDurationMins.value
          : this.estimatedDurationMins,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
      isTemplate: data.isTemplate.present
          ? data.isTemplate.value
          : this.isTemplate,
      tagsJson: data.tagsJson.present ? data.tagsJson.value : this.tagsJson,
