    if (data.containsKey('solved_pixel_scale')) {
      context.handle(
        _solvedPixelScaleMeta,
        solvedPixelScale.isAcceptableOrUnknown(
          data['solved_pixel_scale']!,
          _solvedPixelScaleMeta,
        ),
      );
    }
    if (data.containsKey('captured_at')) {
      context.handle(
        _capturedAtMeta,
        capturedAt.isAcceptableOrUnknown(data['captured_at']!, _capturedAtMeta),
      );
    } else if (isInserting) {
      context.missing(_capturedAtMeta);
    }
    if (data.containsKey('created_at')) {
      context.handle(
        _createdAtMeta,
        createdAt.isAcceptableOrUnknown(data['created_at']!, _createdAtMeta),
      );
    }
    if (data.containsKey('atlas_folded_at')) {
      context.handle(
        _atlasFoldedAtMeta,
        atlasFoldedAt.isAcceptableOrUnknown(
          data['atlas_folded_at']!,
          _atlasFoldedAtMeta,
        ),
      );
    }
    if (data.containsKey('is_accepted')) {
      context.handle(
        _isAcceptedMeta,
        isAccepted.isAcceptableOrUnknown(data['is_accepted']!, _isAcceptedMeta),
      );
    }
    if (data.containsKey('rejection_reason')) {
      context.handle(
        _rejectionReasonMeta,
        rejectionReason.isAcceptableOrUnknown(
          data['rejection_reason']!,
          _rejectionReasonMeta,
        ),
      );
    }
    return context;
  }

