    int? tileId,
    int? healpixOrder,
    int? channels,
    double? centerRaDeg,
    double? centerDecDeg,
    double? coverageMean,
    int? totalFrames,
    double? integrationSeconds,
    int? swarmOverlayFrames,
    double? swarmOverlayIntegrationSeconds,
    String? sidecarPath,
    Value<int?> lastFoldSessionId = const Value.absent(),
